TN.RE_ALTERACAO = / (mudar|alterar|trocar|troca|acrescentar|adicionar|tirar|remover) .* (pedido|tamanho|quantidade|cor|arte|logo|endere[çc]o)| (boleto|segunda via|pix|pagamento|parcela|nota fiscal| nf )/i;
TN.notaNps = (texto) => {
  const t = String(texto || '').trim();
  const m = t.match(/(?:^|\D)(10|[0-9])(?:\D|$)/);
  if (!m) return null;
  const n = +m[1];
  // "nota 9", "9", "dou um 10", "9/10": aceita; evita pegar número de pedido/quantidade ("40 camisetas")
  if (/\d{3,}/.test(t) && !/ (nota|avalia|recomend|dou|daria) /i.test(t) && !/^\s*(10|[0-9])\s*(/\s*10)?\s*$/.test(t)) return null;
  return n;
};
