// ----- decisão do próximo passo (coração da régua) -----
// Entrada (tudo já lido pelo nó): deal do CS, status de Produção, atributos do contato, estado da conversa, agora.
// Saída: { acao, ... } ou { acao: 'nada', motivo }. NUNCA manda duas coisas no mesmo ciclo para o mesmo negócio.
//   acao: 'acolher' | 'toque' | 'pronto' | 'entregue_nps' | 'lembrete_nps' | 'encerrar' | 'nada'
TN.decidir = (ctx) => {
  const { deal, producao, attrs, conversa, agoraMs, cfg } = ctx;
  const etapa = Number(deal.stage_id);
  const regua = String((attrs && attrs.toninho_regua) || '');
  if (regua === 'optout' || regua === 'encerrado') return { acao: 'nada', motivo: 'régua ' + regua };
  if (conversa && conversa.optout) return { acao: 'nada', motivo: 'etiqueta opt-out/sem-followup' };
  if (conversa && conversa.humanoFalando) return { acao: 'nada', motivo: 'conversa aberta com humano (' + conversa.humanoFalando + ')' };
  if (conversa && conversa.escalada) return { acao: 'nada', motivo: 'escalada ao humano em aberto' };
  if (conversa && conversa.clienteEsperando) return { acao: 'nada', motivo: 'cliente falou por último: a Conversa responde, não a Régua' };
  const gapOk = TN.horasDesdeIso(attrs && attrs.toninho_passo_em, agoraMs) >= (cfg.GAP_MIN_H || 20);
  const toques = TN.lerToques(attrs);
  const st = producao || TN.statusProducao(null);

  // 1. Acolhimento: primeira mensagem, uma vez só.
  if (etapa === TN.ETAPA.ACOLHIMENTO) {
    if (toques.includes('acolhimento')) return { acao: 'nada', motivo: 'acolhido, aguardando mover (campo de prazo ausente?)' };
    return { acao: 'acolher', passo: 'acolhimento' };
  }

  // 2. Produção chegou em pronto/expedição/a caminho enquanto o CS ainda está "Em produção": avisa e move.
  if (TN.ETAPAS_PRODUCAO_CS.includes(etapa)) {
    if (st.ordem >= 9) return gapOk ? { acao: 'entregue_nps', passo: 'entregue', moverPara: TN.ETAPA.FEEDBACK } : { acao: 'nada', motivo: 'entregue, mas gap < 20h' };
    if (st.ordem >= 6) return gapOk ? { acao: 'pronto', passo: 'pronto', moverPara: TN.ETAPA.PRONTO } : { acao: 'nada', motivo: 'pronto, mas gap < 20h' };
    const dias = TN.diasDesde(deal.last_stage_updated_at || deal.stage_changed_at || deal.updated_at, agoraMs);
    const cad = TN.CADENCIA[etapa] || [];
    for (let i = 0; i < cad.length; i++) {
      const passo = 'p' + (i + 1);
      if (toques.includes(passo)) continue;
      if (dias !== null && dias >= cad[i]) return gapOk ? { acao: 'toque', passo, dia: cad[i], diasNaEtapa: dias, especial: etapa === TN.ETAPA.ESPECIAL } : { acao: 'nada', motivo: 'toque ' + passo + ' devido, mas gap < 20h' };
      return { acao: 'nada', motivo: 'próximo toque ' + passo + ' no dia ' + cad[i] + ' (hoje é dia ' + dias + ')' };
    }
    return { acao: 'nada', motivo: 'cadência completa; aguardando produção ficar pronta (' + st.chave + ')' };
  }

  // 3. Pedido pronto: expedição/a caminho são avisos extras; entregue abre o NPS; senão D10/D20/D30 "já chegou?".
  if (etapa === TN.ETAPA.PRONTO) {
    if (st.ordem >= 9) return gapOk ? { acao: 'entregue_nps', passo: 'entregue', moverPara: TN.ETAPA.FEEDBACK } : { acao: 'nada', motivo: 'entregue, mas gap < 20h' };
    if (st.chave === 'a_caminho' && !toques.includes('a_caminho')) return gapOk ? { acao: 'toque', passo: 'a_caminho', statusExtra: true } : { acao: 'nada', motivo: 'a caminho, mas gap < 20h' };
    const dias = TN.diasDesde(deal.last_stage_updated_at || deal.stage_changed_at || deal.updated_at, agoraMs);
    const cad = TN.CADENCIA[etapa];
    for (let i = 0; i < cad.length; i++) {
      const passo = 'chegou' + (i + 1);
      if (toques.includes(passo)) continue;
      if (dias !== null && dias >= cad[i]) return gapOk ? { acao: 'toque', passo, dia: cad[i], diasNaEtapa: dias, perguntaEntrega: true } : { acao: 'nada', motivo: passo + ' devido, mas gap < 20h' };
      return { acao: 'nada', motivo: 'próximo "já chegou?" no dia ' + cad[i] + ' (hoje é dia ' + dias + ')' };
    }
    return { acao: 'nada', motivo: '3 perguntas de entrega sem resposta; Vinícius decide (nota já deixada)' };
  }

  // 4. Coleta de feedback: NPS pedido; lembretes D+3 e D+7; depois encerra.
  if (etapa === TN.ETAPA.FEEDBACK) {
    if (attrs && attrs.nps_nota !== undefined && attrs.nps_nota !== null && attrs.nps_nota !== '') {
      return toques.includes('encerrar') ? { acao: 'nada', motivo: 'encerrado' } : { acao: 'encerrar', passo: 'encerrar' };
    }
    if (!toques.includes('entregue')) return gapOk ? { acao: 'entregue_nps', passo: 'entregue' } : { acao: 'nada', motivo: 'NPS inicial, mas gap < 20h' };
    const dias = TN.diasDesde(deal.last_stage_updated_at || deal.stage_changed_at || deal.updated_at, agoraMs);
    const cad = TN.CADENCIA[etapa];
    for (let i = 0; i < cad.length; i++) {
      const passo = 'nps' + (i + 1);
      if (toques.includes(passo)) continue;
      if (dias !== null && dias >= cad[i]) return gapOk ? { acao: 'lembrete_nps', passo, dia: cad[i] } : { acao: 'nada', motivo: passo + ' devido, mas gap < 20h' };
      return { acao: 'nada', motivo: 'próximo lembrete de NPS no dia ' + cad[i] + ' (hoje é dia ' + dias + ')' };
    }
    return toques.includes('encerrar') ? { acao: 'nada', motivo: 'encerrado sem NPS' } : { acao: 'encerrar', passo: 'encerrar', semNps: true };
  }
  return { acao: 'nada', motivo: 'etapa fora do fluxo (' + etapa + ')' };
};

// ----- textos dos toques (texto livre, dentro da janela). Tom por tipo de cliente. -----
TN.informal = (tipo) => ['terceirao', 'faculdade', 'pessoa_fisica'].includes(String(tipo || '').toLowerCase());
TN.texto = (acao, v) => {
  const inf = TN.informal(v.tipo);
  const nome = v.nome ? (inf ? 'Oi ' + v.nome + '!' : 'Olá ' + v.nome + ',') : (inf ? 'Oi!' : 'Olá,');
  const ped = v.pedido ? ' ' + v.pedido : '';
  const resumo = v.resumo ? ' (' + v.resumo + ')' : '';
  const prazo = v.prazo ? (inf ? ' O prazo combinado é de ' + v.prazo + ' dias.' : ' O prazo combinado é de ' + v.prazo + ' dias corridos a partir da aprovação.') : '';
  const rast = v.rastreio ? ' Rastreio: ' + v.rastreio + '.' : '';
  switch (acao) {
    case 'acolher':
      return inf
        ? nome + ' Toninho aqui, da T&M 👋 Vou acompanhar o pedido' + ped + resumo + ' da turma com você até chegar.' + prazo + ' Tem alguma data que vocês precisam ter em mãos? Me conta que eu já anoto.'
        : nome + ' aqui é o Toninho, da T&M. Eu vou acompanhar o pedido' + ped + resumo + ' com você até a entrega, direto por aqui.' + prazo + ' Vocês têm alguma data limite para receber? Se tiver, me avisa que já deixo registrado.';
    case 'toque':
      if (v.perguntaEntrega) return inf
        ? nome + ' O pedido' + ped + ' já saiu daqui. Chegou aí? Me conta como ficou!'
        : nome + ' o pedido' + ped + ' já saiu da nossa expedição. Ele chegou? Se puder, me conta como ficou o resultado.';
      if (v.statusExtra) return inf
        ? nome + ' O pedido' + ped + ' foi coletado e tá a caminho.' + rast + ' Quando chegar, pede pra quem receber conferir o volume e, se der, gravar um vídeo abrindo a caixa.'
        : nome + ' o pedido' + ped + ' foi coletado e está a caminho.' + rast + ' Quando chegar, peça para quem receber conferir o volume e, se possível, gravar um vídeo abrindo a caixa: é a garantia de vocês para qualquer imprevisto.';
      if (v.semMudanca) return inf
        ? nome + ' O pedido' + ped + ' segue ' + v.status + ', sem novidade e dentro do prazo. Te aviso quando mudar de fase.'
        : nome + ' o pedido' + ped + ' segue ' + v.status + ', sem novidade e dentro do prazo. Te aviso assim que mudar de fase.';
      return inf
        ? nome + ' Posição do pedido' + ped + ': ' + v.status + '. Tá dentro do prazo. Se precisar de algo é só chamar.'
        : nome + ' passando com a posição do pedido' + ped + ': ' + v.status + '. Segue dentro do prazo combinado. Qualquer dúvida é só responder aqui.';
    case 'pronto':
      return (inf ? nome + ' Boa notícia: ' : nome + ' boa notícia: ') + 'o pedido' + ped + ' está pronto! Agora ele segue para a expedição e te aviso quando sair.' + (v.financeiro ? ' O financeiro vai alinhar a parcela final com vocês por aqui.' : '');
    case 'entregue_nps':
      return inf
        ? nome + ' Consta aqui que o pedido' + ped + ' foi entregue. Chegou tudo certo? E, pra fechar: de 0 a 10, o quanto você recomendaria a T&M pra outra turma? Pode mandar também o que achou das peças.'
        : nome + ' consta aqui que o pedido' + ped + ' foi entregue. Chegou tudo certo? Para fechar o acompanhamento: de 0 a 10, o quanto você recomendaria a T&M para outra empresa? Se quiser, me diz também o que foi melhor e o que podia melhorar.';
    case 'lembrete_nps':
      return inf
        ? nome + ' Ainda não recebi sua nota do pedido' + ped + '. É rapidinho: de 0 a 10, o quanto você recomendaria a T&M?'
        : nome + ' ainda não recebi a sua avaliação do pedido' + ped + '. Responder leva 10 segundos: de 0 a 10, o quanto você recomendaria a T&M?';
    case 'encerrar':
      return v.semNps
        ? (inf ? nome + ' Vou encerrar o acompanhamento do pedido' + ped + ' por aqui. Qualquer coisa sobre ele é só responder esta conversa que eu retomo.' : nome + ' encerro o acompanhamento do pedido' + ped + ' por aqui. Qualquer coisa sobre ele, é só responder esta conversa que eu retomo. Obrigado pela confiança.')
        : (inf ? 'Obrigado, ' + (v.nome || 'pessoal') + '! Encerro o acompanhamento do pedido' + ped + ' por aqui. Qualquer coisa é só responder esta conversa que eu retomo. Foi um prazer acompanhar vocês.' : 'Obrigado, ' + (v.nome || 'e até a próxima') + '. Encerro o acompanhamento do pedido' + ped + ' por aqui. Qualquer coisa sobre ele, é só responder esta conversa que eu retomo. Foi um prazer acompanhar vocês.');
    default:
      return '';
  }
};

// ----- guardas da conversa (regra dura = código) -----
TN.RE_OPTOUT = / (para|pare|parem|parar)\s+de\s+(me\s+)?(mandar|enviar)|n[aã]o\s+quero\s+mais\s+(receber|mensagem|mensagens)|me\s+tira\s+da\s+lista|descadastr|sair\s+da\s+lista|cancela\s+(as\s+)?mensagens| remov(a|e)\s+meu\s+n[uú]mero/i;
TN.RE_HUMANO = / (falar|conversar)\s+com\s+(um\s+|uma\s+|o\s+|a\s+|algu[eé]m|atendente|pessoa|humano|vendedor|vendedora|gerente|vin[ií]cius)| atendente | humano | gerente /i;
TN.RE_RECLAMACAO = / (p[eé]ssim|absurd|atrasad|atraso|errad|faltou|faltando|defeit|rasgad|manchad|veio diferente|n[aã]o chegou|n[aã]o recebi|cancelar|reembolso|estorno|procon|reclama|decepcion|horr[ií]vel|vergonha)/i;
TN.RE_ALTERACAO = / (mudar|alterar|trocar|troca|acrescentar|adicionar|tirar|remover) .* (pedido|tamanho|quantidade|cor|arte|logo|endere[çc]o)| (boleto|segunda via|pix|pagamento|parcela|nota fiscal| nf )/i;
TN.notaNps = (texto) => {
  const t = String(texto || '').trim();
  const m = t.match(/(?:^|\D)(10|[0-9])(?:\D|$)/);
  if (!m) return null;
  const n = +m[1];
  // "nota 9", "9", "dou um 10", "9/10": aceita; evita pegar número de pedido/quantidade ("40 camisetas")
  if (/\d{3,}/.test(t) && !/ (nota|avalia|recomend|dou|daria) /i.test(t) && !/^\s*(10|[0-9])\s*(/\s*10)?\s*$/.test(t)) return null;
  return n;
};
TN.guardas = (msg) => {
  const t = String(msg || '');
  if (TN.RE_OPTOUT.test(t)) return 'optout';
  if (TN.RE_HUMANO.test(t) || TN.RE_RECLAMACAO.test(t) || TN.RE_ALTERACAO.test(t)) return 'escalar';
  return null;
};
TN.classeNps = (n) => (n >= 9 ? 'promotor' : n >= 7 ? 'neutro' : 'detrator');
// <<< TONINHO COMUM (fim)
const ctx = $('Contexto').first().json;
const ia = $json;
const dry = CONFIG.SIMULACAO;
const H = { api_access_token: CONFIG.ADMIN_TOKEN };
const HT = { api_access_token: CONFIG.TONINHO_TOKEN || CONFIG.ADMIN_TOKEN };
const HP = { token: CONFIG.PIPERUN_TOKEN };
const escritas = [];
const cw = async (m, p, body, h) => this.helpers.httpRequest({ method: m, url: `${CONFIG.CW}/api/v1/accounts/${CONFIG.ACC}` + p, headers: h || H, body, json: true, timeout: 15000 });
const prTry = async (m, p, body) => { try { const r = await this.helpers.httpRequest({ method: m, url: CONFIG.PIPERUN + p, headers: HP, body, json: true, timeout: 20000, returnFullResponse: true, ignoreHttpStatusErrors: true }); const code = Number(r.statusCode || 200); return { ok: code < 300, status: code, body: r.body }; } catch (x) { return { ok: false, status: 0, body: String(x.message).slice(0, 200) }; } };
const escrever = async (d, fn) => { escritas.push(d); if (dry) return { simulado: true }; return fn(); };
const convId = ctx.conversation_id;
// 1. ler a tool
let out = {};
try { const tu = ((ia.content) || []).find(c => c.type === 'tool_use'); out = (tu && tu.input) || {}; } catch (x) {}
if (!out.decisao) out = { resposta: '', decisao: 'escalar', motivo_escalada: 'a IA não devolveu decisão' };
let decisao = String(out.decisao);
let resposta = String(out.resposta || '').replace(/—/g, ',').replace(/\[[^\]]*\]/g, '').trim();
const motivos = [];
// 2. guardas (código vence prompt)
if (ctx.guarda === 'optout') { decisao = 'optout'; motivos.push('guarda: termos de opt-out'); if (!resposta) resposta = 'Tranquilo, não te mando mais nada por aqui. Qualquer coisa do pedido é só chamar.'; }
else if (ctx.guarda === 'escalar' && !['escalar', 'optout'].includes(decisao)) { decisao = 'escalar'; motivos.push('guarda: termos de humano/reclamação/alteração'); out.motivo_escalada = out.motivo_escalada || 'cliente pediu humano, reclamou ou pediu alteração: ' + ctx.content.slice(0, 120); }
if (decisao === 'nps') {
  const n = Number.isInteger(out.nps_nota) && out.nps_nota >= 0 && out.nps_nota <= 10 ? out.nps_nota : ctx.nota_lida;
  if (n === null || n === undefined) { decisao = 'feedback'; motivos.push('nps sem nota válida: vira feedback'); } else out.nps_nota = n;
}
if (decisao === 'continuar' && ctx.turnos_toninho >= CONFIG.MAX_TURNOS) { decisao = 'escalar'; out.motivo_escalada = 'assunto não resolvido em ' + ctx.turnos_toninho + ' respostas'; motivos.push('guarda: máximo de turnos'); }
if (decisao === 'escalar' && !resposta) resposta = TN.informal(ctx.tipo) ? 'Entendi! Vou chamar o Vinícius, do pós-vendas, que resolve isso contigo por aqui ' + (ctx.dentro_expediente ? 'ainda hoje.' : 'no próximo horário de atendimento, a partir das 8h.') : 'Entendi. Vou passar isso para o Vinícius, do nosso pós-vendas, que assume por aqui e te retorna ' + (ctx.dentro_expediente ? 'ainda hoje.' : 'no próximo horário de atendimento, a partir das 8h.') + ' Já deixei o resumo com ele.';
// 3. responder
try { await cw('POST', `/conversations/${convId}/toggle_typing_status`, { typing_status: 'off' }, HT); } catch (x) {}
if (resposta) await escrever(`resposta -> conversa ${convId}: ${resposta}`, () => cw('POST', `/conversations/${convId}/messages`, { content: CONFIG.ASSINATURA ? resposta + '

' + CONFIG.ASSINATURA : resposta, message_type: 'outgoing', private: false }, HT));
// 4. ações
const attrs = Object.assign({}, ctx.attrs);
const novos = {};
const agoraIso = new Date().toISOString();
const dealId = ctx.deal_cs && ctx.deal_cs.id;
const notaPipe = async (t) => { if (!dealId) return; if (!CONFIG.ESCREVER_PIPERUN) { escritas.push(`[PipeRun bloqueado, pendência 1] nota no negócio ${dealId}: ${t}`); return; } await escrever(`nota no negócio ${dealId}: ${t}`, () => prTry('POST', '/notes', { deal_id: dealId, text: 'TONINHO: ' + t })); };
const moverPipe = async (etapa) => { if (!dealId || !etapa || Number(ctx.deal_cs.stage_id) === etapa) return; if (!CONFIG.ESCREVER_PIPERUN) { escritas.push(`[PipeRun bloqueado, pendência 1] mover negócio ${dealId} para ${TN.NOME_ETAPA[etapa]}`); return; } await escrever(`mover negócio ${dealId} -> ${TN.NOME_ETAPA[etapa]}`, () => prTry('PUT', `/deals/${dealId}`, { stage_id: etapa })); };
const notaPrivada = async (t) => escrever(`nota privada na conversa ${convId}: ${t}`, () => cw('POST', `/conversations/${convId}/messages`, { content: t, message_type: 'outgoing', private: true }));
const etiquetar = async (novas) => { const labels = Array.from(new Set([...(ctx.labels || []), ...novas])); await escrever(`etiquetas da conversa ${convId}: ${labels.join(',')}`, () => cw('POST', `/conversations/${convId}/labels`, { labels })); };
const escalarPara = async (agenteId, motivo) => {
  novos.toninho_regua = 'escalado'; novos.toninho_escalada_em = agoraIso; novos.toninho_escalada_motivo = String(motivo).slice(0, 200);
  await escrever(`conversa ${convId}: responsável ${agenteId}, etiqueta responder`, async () => { await cw('POST', `/conversations/${convId}/assignments`, { assignee_id: agenteId }); await cw('POST', `/conversations/${convId}/assignments`, { team_id: CONFIG.TEAM_POSVENDAS }); });
  await etiquetar(['responder']);
  await notaPrivada(`⚠️ TONINHO ESCALOU: ${motivo}
Pedido ${ctx.numero || '?'} | produção: ${ctx.producao.chave} | etapa CS: ${ctx.deal_cs ? TN.NOME_ETAPA[ctx.deal_cs.stage_id] : '?'}
Última mensagem do cliente: "${ctx.content.slice(0, 300)}"
Quando resolver, devolva a conversa ao Toninho (responsável "Toninho (IA)") para a régua continuar.`);
  await notaPipe(`escalado ao humano: ${motivo}`);
};
switch (decisao) {
  case 'prazo_cliente': {
    if (/^\d{4}-\d{2}-\d{2}$/.test(String(out.prazo_cliente || ''))) { novos.prazo_cliente = out.prazo_cliente; await notaPipe(`cliente informou data limite ${out.prazo_cliente}.`); }
    break; }
  case 'feedback': { if (out.feedback) { novos.feedback_texto = String(out.feedback).slice(0, 500); await notaPipe(`feedback do cliente: ${String(out.feedback).slice(0, 300)}`); } break; }
  case 'entregue': { novos.entregue_em = agoraIso; await notaPipe('cliente confirmou a entrega.'); await moverPipe(TN.ETAPA.FEEDBACK); break; }
  case 'nps': {
    const n = out.nps_nota, classe = TN.classeNps(n);
    Object.assign(novos, { nps_nota: n, nps_comentario: String(out.feedback || ctx.content).slice(0, 500), nps_em: agoraIso, toninho_regua: 'nps' });
    if (!attrs.entregue_em) novos.entregue_em = agoraIso;
    await etiquetar(['nps-' + classe]);
    await notaPipe(`NPS ${n} (${classe})${out.feedback ? ': ' + String(out.feedback).slice(0, 300) : ''}`);
    await moverPipe(TN.ETAPA.FEEDBACK);
    if (ctx.deal_cs && ctx.deal_cs.company_id) { if (!CONFIG.ESCREVER_PIPERUN) escritas.push(`[PipeRun bloqueado, pendência 1] nps_score=${n} na empresa ${ctx.deal_cs.company_id}`); else await escrever(`nps_score=${n} na empresa ${ctx.deal_cs.company_id}`, () => prTry('PUT', `/companies/${ctx.deal_cs.company_id}`, { nps_score: n })); }
    if (classe === 'detrator') { await escalarPara(CONFIG.VINICIUS_AGENT_ID, `NPS detrator (${n}). Marcelo deve ser avisado (pendência 9).`); await notaPrivada(`@Marcelo NPS ${n} no pedido ${ctx.numero || '?'}: cliente insatisfeito, Vinícius assumiu.`); }
    break; }
  case 'escalar': { const recompra = /recompra|novo pedido|outro pedido/i.test(String(out.motivo_escalada || '')); await escalarPara(recompra && CONFIG.ESCALAR_RECOMPRA_PARA_VENDEDOR ? CONFIG.VINICIUS_AGENT_ID : CONFIG.VINICIUS_AGENT_ID, out.motivo_escalada || 'sem motivo informado'); break; }
  case 'optout': { novos.toninho_regua = 'optout'; await etiquetar(['opt-out']); await notaPipe('cliente pediu para não receber mais mensagens (opt-out). Acompanhamento manual.'); await notaPrivada('🚫 Opt-out registrado pelo Toninho. Nenhuma régua toca mais neste contato.'); break; }
  case 'encerrar': { novos.toninho_regua = 'encerrado'; novos.toninho_toques = TN.marcarToque(attrs, 'encerrar'); await notaPipe('acompanhamento encerrado na conversa.'); if (CONFIG.RESOLVER_AO_ENCERRAR) await escrever(`resolver conversa ${convId}`, () => cw('POST', `/conversations/${convId}/toggle_status`, { status: 'resolved' })); break; }
  default: break;
}
if (Object.keys(novos).length) await escrever(`atributos do contato ${ctx.contact_id}: ${JSON.stringify(novos)}`, () => cw('PUT', `/contacts/${ctx.contact_id}`, { custom_attributes: Object.assign(attrs, novos) }));
return [{ json: { ok: true, simulacao: dry, decisao, decisao_ia: out.decisao, motivos, resposta, escritas, uso: ia.usage || null } }];
